code_example:
#include <vector>
#include <algorithm>
#include <iostream>
#include <iterator>

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    std::vector<int> result;
    result.reserve(data.size());

    // Using std::transform with a lambda to square each element
    std::transform(data.begin(), data.end(), std::back_inserter(result),
                   [](int x) { return x * x; });

    // Output the transformed data
    for (const auto& val : result) {
        std::cout << val << ' ';
    }
    std::cout << std::endl;

    // Using std::merge to combine two sorted ranges
    std::vector<int> data2 = {0, 2, 4, 6, 8};
    std::vector<int> merged;
    merged.reserve(data.size() + data2.size());
    std::merge(data.begin(), data.end(), data2.begin(), data2.end(),
               std::back_inserter(merged));

    // Output the merged data
    for (const auto& val : merged) {
        std::cout << val << ' ';
    }
    std::cout << std::endl;
    return 0;
}
